sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
uniform float blur;
layout(color) uniform half4 glowColor;
uniform float intensity;
uniform float whiteCore;
uniform float coreBoost;
uniform float flicker;
uniform float flickerSpeed;
uniform float opacity;
float4 texT(float2 p) {
    return float4(image.eval(p));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
half4 main(float2 coord) {
    float4 c = texT(coord);
    float4 b = float4(blurred.eval(coord));
    float fl = 1.0 - flicker * (0.5 + 0.5 * sin(time * flickerSpeed + hash21(float2(floor(time * flickerSpeed), 2.0)) * 6.0));
    float3 core = mix(unp(c), float3(1.0), whiteCore) * coreBoost;
    float4 textL = float4(core * c.a, c.a);
    float ga = saturate(b.a * intensity) * fl;
    float4 glowL = float4(float3(glowColor.rgb) * ga, ga);
    return fin(c, textL + glowL * (1.0 - textL.a), opacity);
}
